#!/usr/bin/env bash
# gen-buildinfo.sh - write build identity header (only if content changed).
# Usage: scripts/gen-buildinfo.sh OUTPUT_HEADER MODE FLAVOR VERSION
# Handles a missing git repository or an unavailable hash ("unknown").
set -eu

OUT="$1"; MODE="$2"; FLAVOR="$3"; VERSION="$4"

rev="$(git rev-parse --short=12 HEAD 2>/dev/null || true)"
[ -n "$rev" ] || rev=unknown

mkdir -p "$(dirname "$OUT")"
tmp="$OUT.tmp"
cat >"$tmp" <<EOF
/* Generated by scripts/gen-buildinfo.sh - do not edit. */
#ifndef ATAOS_BUILDINFO_H
#define ATAOS_BUILDINFO_H
#define ATAOS_VERSION "$VERSION"
#define ATAOS_BUILD_MODE "$MODE"
#define ATAOS_BUILD_FLAVOR "$FLAVOR"
#define ATAOS_GIT_REV "$rev"
#endif
EOF
if [ -f "$OUT" ] && cmp -s "$tmp" "$OUT"; then
    rm -f "$tmp"
else
    mv "$tmp" "$OUT"
fi
